import os
import time
from typing import Any, Dict, Optional

import requests


class DeepgramBatchSpeechToText:
    def __init__(self, api_key: Optional[str] = None, base_url: str = "https://api.deepgram.com"):
        self.api_key = api_key or os.getenv("DEEPGRAM_API_KEY")
        if not self.api_key:
            raise ValueError("Missing Deepgram API key. Set DEEPGRAM_API_KEY or pass api_key.")
        self.base_url = base_url.rstrip("/")
        self.headers = {
            "Authorization": f"Token {self.api_key}",
            "Content-Type": "application/json",
        }

    def _request(self, method: str, path: str, **kwargs) -> Dict[str, Any]:
        url = f"{self.base_url}{path}"
        response = requests.request(method, url, headers=self.headers, timeout=30, **kwargs)
        response.raise_for_status()
        if response.status_code == 204:
            return {}
        return response.json()

    def poll_transcription_job(
        self,
        job_id: str,
        poll_interval: float = 5.0,
        timeout: float = 600.0,
    ) -> str:
        deadline = time.time() + timeout
        while True:
            data = self._request("GET", f"/v1/listen/{job_id}")
            status = (data.get("status") or "").lower()

            if status in {"completed", "done", "finished", "succeeded"}:
                result = data.get("results") or data.get("result") or data
                channels = result.get("channels") if isinstance(result, dict) else None
                if channels and isinstance(channels, list):
                    alternatives = channels[0].get("alternatives") or []
                    if alternatives:
                        transcript = alternatives[0].get("transcript", "")
                        if transcript:
                            return transcript
                transcript = result.get("transcript") if isinstance(result, dict) else None
                if transcript:
                    return transcript
                raise RuntimeError("Transcription completed but no transcript was found.")

            if status in {"failed", "error", "canceled", "cancelled"}:
                raise RuntimeError(f"Transcription job {job_id} failed with status: {status}")

            if time.time() >= deadline:
                raise TimeoutError(f"Timed out waiting for transcription job {job_id}")

            time.sleep(poll_interval)


def poll_transcription_job(job_id: str, poll_interval: float = 5.0, timeout: float = 600.0, api_key: Optional[str] = None) -> str:
    return DeepgramBatchSpeechToText(api_key=api_key).poll_transcription_job(
        job_id=job_id,
        poll_interval=poll_interval,
        timeout=timeout,
    )
